// Validates and normalizes the delivery-zone request. No external calls.
const MAX_TEXT = 100;
const DEFAULT_CITY = 'Karachi';

const raw = $input.first().json || {};
let body = raw.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}

const errors = [];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Request body must be a JSON object.');
  body = {};
}

let area = null;
if (body.area === undefined || body.area === null) {
  errors.push('area is required.');
} else if (typeof body.area !== 'string') {
  errors.push('area must be a string.');
} else if (body.area.trim().length === 0) {
  errors.push('area must not be empty.');
} else if (body.area.trim().length > MAX_TEXT) {
  errors.push('area must be at most ' + MAX_TEXT + ' characters.');
} else {
  area = body.area.trim();
}

let city = DEFAULT_CITY;
if (body.city !== undefined && body.city !== null) {
  if (typeof body.city !== 'string') {
    errors.push('city must be a string when provided.');
  } else if (body.city.trim().length > MAX_TEXT) {
    errors.push('city must be at most ' + MAX_TEXT + ' characters.');
  } else if (body.city.trim().length > 0) {
    city = body.city.trim();
  }
}

if (errors.length > 0) {
  return [{ json: {
    valid: false,
    statusCode: 400,
    body: {
      success: false,
      serviceable: false,
      error: 'invalid_request',
      message: 'Invalid delivery request: ' + errors.join(' '),
      details: errors,
    },
  } }];
}

return [{ json: { valid: true, request: { area: area, city: city } } }];

// Matches the requested area/city against Delivery_Zones rows. Never invents fees or ETAs.
try {
  const req = $('Validate Delivery Request').first().json.request;
  const items = $input.all();

  const dbError = function (code, message) {
    return [{ json: { statusCode: code === 'database_unavailable' ? 503 : 500, body: {
      success: false, serviceable: false, error: code, message: message,
    } } }];
  };

  // Google Sheets read failure (node continues with an error item).
  if (items.some(function (i) { return i && i.json && i.json.error; })) {
    return dbError('database_unavailable', 'The delivery zone database could not be read right now. Please try again shortly.');
  }

  const rows = items
    .map(function (i) { return i && i.json ? i.json : {}; })
    .filter(function (r) { return Object.keys(r).length > 0; });

  if (rows.length === 0) {
    return dbError('configuration_error', 'The delivery zone database has no zone records configured.');
  }

  const REQUIRED = ['zone_id', 'area_name', 'city', 'is_serviceable', 'delivery_fee', 'estimated_delivery_minutes'];
  const present = {};
  rows.forEach(function (r) { Object.keys(r).forEach(function (k) { present[k] = true; }); });
  const missingCols = REQUIRED.filter(function (c) { return !present[c]; });
  if (missingCols.length > 0) {
    return dbError('configuration_error', 'The delivery zone database is missing required columns: ' + missingCols.join(', ') + '.');
  }

  const str = function (v) { return v === null || v === undefined ? '' : String(v).trim(); };
  const norm = function (v) { return str(v).toLowerCase(); };
  const isTrue = function (v) {
    if (v === true) return true;
    if (typeof v === 'number') return v === 1;
    if (typeof v !== 'string') return false;
    const s = v.trim().toLowerCase();
    return s === 'true' || s === 'yes' || s === '1';
  };
  const toNonNegNumber = function (v) {
    if (v === null || v === undefined) return null;
    if (typeof v === 'number') return Number.isFinite(v) && v >= 0 ? v : null;
    const s = String(v).trim();
    if (s === '') return null;
    const n = Number(s.replace(/,/g, ''));
    return Number.isFinite(n) && n >= 0 ? n : null;
  };

  const wantArea = norm(req.area);
  const wantCity = norm(req.city);
  const matches = rows.filter(function (r) {
    return norm(r.area_name) === wantArea && norm(r.city) === wantCity;
  });

  if (matches.length === 0) {
    return [{ json: { statusCode: 404, body: {
      success: false, serviceable: false, error: 'area_not_found',
      area: req.area, city: req.city,
      message: 'We could not find "' + req.area + '" in ' + req.city + ' in our delivery zones.',
    } } }];
  }

  if (matches.length > 1) {
    return [{ json: { statusCode: 409, body: {
      success: false, serviceable: false, error: 'ambiguous_zone',
      area: req.area, city: req.city,
      matching_zone_ids: matches.map(function (r) { return str(r.zone_id); }),
      message: 'Multiple delivery zones match this area and city. The delivery zone database needs to be corrected before delivery can be confirmed.',
    } } }];
  }

  const z = matches[0];
  const zoneInfo = { zone_id: str(z.zone_id), area_name: str(z.area_name), city: str(z.city) };

  if (!isTrue(z.is_serviceable)) {
    const notes = str(z.notes);
    return [{ json: { statusCode: 200, body: {
      success: true, serviceable: false, error: 'delivery_unavailable',
      zone: zoneInfo,
      message: 'Delivery is currently not available in this area.' + (notes ? ' ' + notes : ''),
    } } }];
  }

  const fee = toNonNegNumber(z.delivery_fee);
  const eta = toNonNegNumber(z.estimated_delivery_minutes);
  if (!zoneInfo.zone_id || fee === null || eta === null) {
    const bad = [];
    if (!zoneInfo.zone_id) bad.push('zone_id');
    if (fee === null) bad.push('delivery_fee');
    if (eta === null) bad.push('estimated_delivery_minutes');
    return dbError('configuration_error', 'The matching delivery zone has missing or invalid data (' + bad.join(', ') + '), so delivery cannot be confirmed.');
  }

  return [{ json: { statusCode: 200, body: {
    success: true, serviceable: true,
    zone: {
      zone_id: zoneInfo.zone_id,
      area_name: zoneInfo.area_name,
      city: zoneInfo.city,
      delivery_fee: fee,
      estimated_delivery_minutes: eta,
    },
    message: 'Delivery is available in this area.',
  } } }];
} catch (err) {
  return [{ json: { statusCode: 500, body: {
    success: false, serviceable: false, error: 'internal_error',
    message: 'Something went wrong while checking the delivery zone. Please try again.',
  } } }];
}
